import React, { useState, useRef, useCallback, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const [stream, setStream] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState("info");
  const [autoMode, setAutoMode] = useState(false);

  // ================= DÉMARRER LA CAMÉRA =================
  const startCamera = useCallback(async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user", width: 1280, height: 720 }
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
      setMessage("");
    } catch (err) {
      setMessage("❌ Impossible d'accéder à la caméra.");
      setMessageType("error");
    }
  }, []);

  // ================= STOPPER LA CAMÉRA (VERSION FIABLE) =================
  const stopCamera = useCallback(() => {
    if (stream) {
      stream.getTracks().forEach(track => {
        track.stop();
      });
      setStream(null);
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setAutoMode(false);        // Arrête aussi le mode auto
    setMessage("📴 Caméra arrêtée");
    setMessageType("info");
  }, [stream]);

  // Démarrer au chargement
  useEffect(() => {
    startCamera();
    return () => stopCamera();   // Nettoyage automatique en quittant l'onglet
  }, [startCamera, stopCamera]);

  // ================= CAPTURE =================
  const handleCapture = useCallback(async () => {
    if (!videoRef.current) return;

    setLoading(true);
    setMessage("⏳ Analyse en cours...");

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageSrc = canvas.toDataURL('image/jpeg', 0.92);

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data || response || {};

      const name = String(data.student || data.student_name || data.name || "Inconnu");
      const confidence = (Number(data.confidence || 0) * 100).toFixed(1);

      if (data.success || name !== "Inconnu") {
        setMessage(`✅ ${name} - Confiance : ${confidence}%`);
        setMessageType("success");
      } else {
        setMessage(String(data.message || data.error || "Visage non reconnu"));
        setMessageType("error");
      }
    } catch (err) {
      setMessage(`❌ ${err.message || "Erreur serveur"}`);
      setMessageType("error");
    } finally {
      setLoading(false);
    }
  }, []);

  // Auto Mode
  useEffect(() => {
    let interval = null;
    if (autoMode && !loading) {
      interval = setInterval(handleCapture, 5000);
    }
    return () => clearInterval(interval);
  }, [autoMode, loading, handleCapture]);

  return (
    <div style={{ padding: '40px', maxWidth: '800px', margin: '0 auto', textAlign: 'center' }}>
      <h1 style={{ marginBottom: '30px' }}>📷 Reconnaissance Faciale</h1>

      <div style={{ 
        borderRadius: '16px', 
        overflow: 'hidden', 
        background: '#000', 
        marginBottom: '30px',
        boxShadow: '0 10px 40px rgba(0,0,0,0.3)'
      }}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={{ width: '100%', height: 'auto', display: 'block' }}
        />
      </div>

      <div style={{ display: 'flex', gap: '15px', marginBottom: '20px' }}>
        <button 
          onClick={handleCapture}
          disabled={loading}
          style={{
            flex: 1,
            padding: '16px',
            fontSize: '17px',
            background: loading ? '#6b7280' : '#4F46E5',
            color: 'white',
            border: 'none',
            borderRadius: '10px',
            cursor: loading ? 'not-allowed' : 'pointer',
            fontWeight: '600'
          }}
        >
          {loading ? '⏳ Analyse...' : '🔍 Capturer & Analyser'}
        </button>

        <button 
          onClick={() => setAutoMode(!autoMode)}
          style={{
            flex: 1,
            padding: '16px',
            fontSize: '17px',
            background: autoMode ? '#EF4444' : '#10B981',
            color: 'white',
            border: 'none',
            borderRadius: '10px',
            cursor: 'pointer',
            fontWeight: '600'
          }}
        >
          {autoMode ? '⏹ STOP AUTO' : '🔄 AUTO SCAN'}
        </button>
      </div>

      {/* Bouton Stop Caméra - Plus visible */}
      <button 
        onClick={stopCamera}
        style={{
          padding: '12px 30px',
          background: '#EF4444',
          color: 'white',
          border: 'none',
          borderRadius: '8px',
          cursor: 'pointer',
          fontSize: '16px',
          fontWeight: '600',
          marginBottom: '30px'
        }}
      >
        🛑 Arrêter la Caméra
      </button>

      {message && (
        <div style={{
          padding: '25px',
          borderRadius: '12px',
          fontSize: '20px',
          backgroundColor: messageType === 'success' ? '#DCFCE7' : '#FEE2E2',
          color: messageType === 'success' ? '#166534' : '#991B1B',
          border: `3px solid ${messageType === 'success' ? '#86EFAC' : '#FECACA'}`
        }}>
          {message}
        </div>
      )}
    </div>
  );
};

export default CameraRecognition;
